import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

const CoursePayment = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { course, student } = location.state || {};

  const handlePayment = () => {
    // Integrate PhonePe or Razorpay logic here
    // On success, navigate to confirmation
    navigate('/confirmation', { state: { course, student } });
  };

  if (!course) return <p className="p-8 text-center text-red-500">Missing payment details. Please restart enrollment.</p>;

  return (
    <div className="p-8 max-w-md mx-auto mt-10 border rounded-lg shadow-lg bg-white text-center text-gray-900">
      <h2 className="text-2xl font-bold mb-6 text-gray-800">Payment Summary</h2>
      
      <div className="text-left bg-gray-50 p-5 rounded-lg mb-6 border border-gray-200">
        <p className="mb-2"><strong className="text-gray-700">Name:</strong> {student?.name}</p>
        <p className="mb-2"><strong className="text-gray-700">Email:</strong> {student?.email}</p>
        <p className="mb-2"><strong className="text-gray-700">Course:</strong> {course.title}</p>
        <div className="mt-4 pt-4 border-t border-gray-200">
          <p className="text-2xl font-extrabold text-green-600">Total Payable: ₹{course.price}</p>
        </div>
      </div>

      {/* Trust & Safety Section */}
      <div className="text-left bg-blue-50 p-4 rounded-lg mb-6 border border-blue-100 text-sm text-gray-700 space-y-3">
        <div className="flex items-start gap-3">
          <span className="text-xl leading-none">🔒</span>
          <p><strong>100% Secure Payment:</strong> Your transaction is protected with bank-grade end-to-end encryption.</p>
        </div>
        <div className="flex items-start gap-3">
          <span className="text-xl leading-none">🛡️</span>
          <p><strong>Safe Online Classes:</strong> Join a secure, verified, and highly interactive online learning environment.</p>
        </div>
        <div className="flex items-start gap-3">
          <span className="text-xl leading-none">📹</span>
          <p><strong>2 Years Video Access:</strong> Never miss out. Get unrestricted access to all recorded session videos for 24 months.</p>
        </div>
      </div>

      <button 
        onClick={handlePayment}
        className="w-full bg-green-600 text-white py-3 rounded-lg font-bold text-lg hover:bg-green-700 transition-colors shadow-md flex items-center justify-center gap-2"
      >
        <span>Pay ₹{course.price} Securely</span>
      </button>
      
      <p className="text-xs text-gray-500 mt-4">
        Guaranteed safe checkout. By proceeding, you agree to our Terms & Conditions.
      </p>
    </div>
  );
};

export default CoursePayment;
